import{_ as s,o as n,c as i,a2 as r,j as t,a,t as l}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Addons Guide — Glacier Pack","description":"What each of the 46 Glacier Pack addons does, where it lives in the hub, what users see on the client side, and practical usage notes.","frontmatter":{"title":"Addons Guide — Glacier Pack","description":"What each of the 46 Glacier Pack addons does, where it lives in the hub, what users see on the client side, and practical usage notes.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/user-guide/addons.md","filePath":"glacier-pack/user-guide/addons.md","lastUpdated":1786286622000}'),d={name:"glacier-pack/user-guide/addons.md"};function c(o,e,h,g,u,p){return n(),i("div",null,[e[4]||(e[4]=r('<h1 id="addons-guide" tabindex="-1">Addons Guide <a class="header-anchor" href="#addons-guide" aria-label="Permalink to &quot;Addons Guide&quot;">​</a></h1><p>One compact brief per addon: what it does, where it lives in the hub, its client-facing surface, and the things worth knowing before you rely on it. Settings and defaults for each addon are in the <a href="./../configuration/reference">Configuration Reference</a>.</p><hr><h2 id="basic-pack" tabindex="-1">Basic pack <a class="header-anchor" href="#basic-pack" aria-label="Permalink to &quot;Basic pack&quot;">​</a></h2><h3 id="audit-log" tabindex="-1">Audit Log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit Log&quot;">​</a></h3><p>A chronological, filterable trail of everything the panel&#39;s stock activity feed records — sign-ins, server power actions, configuration changes, API calls — without SSH or external tools.</p><ul><li><strong>Hub:</strong> <code>?a=audit-log</code> — single pane (filter bar, per-entry detail dialog, retention tools).</li><li><strong>Client surface:</strong> none (root-admin tool).</li><li>One search box matches event names, descriptions, IPs, entry details, actor usernames and API key identifiers; scope, actor-type and date-range filters narrow the feed further.</li><li>Retention tools prune entries older than a chosen number of days or clear the log entirely, both behind confirmation prompts.</li><li>Zero schema changes — the addon ships no tables and no middleware; it reads the <code>activity_logs</code> the panel already writes.</li></ul><h3 id="auto-suspend" tabindex="-1">Auto Suspend <a class="header-anchor" href="#auto-suspend" aria-label="Permalink to &quot;Auto Suspend&quot;">​</a></h3><p>Give any server an expiry date and let the panel enforce it: the owner is warned by email before the date, the server suspends itself when the date passes, and — optionally — servers that outstay a grace period are deleted. Built for trials, prepaid plans and demo machines.</p><ul><li><strong>Hub:</strong> <code>?a=auto-suspend</code> — sub-tabs <strong>Overview</strong>, <strong>Servers</strong> (searchable list with an inline expiry form per row), <strong>History</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> an &quot;Expires in Nd&quot; countdown chip on dashboard server cards (amber near the date, red once overdue) plus a slim notice inside the server view.</li><li>Extending a suspended server&#39;s expiry into the future lifts the suspension automatically on the next scheduler pass; only addon-applied suspensions are auto-delete eligible — manual suspensions are never deleted.</li><li>Everything runs on the stock panel cron (<code>auto-suspend:process</code> every five minutes); warning emails use the panel&#39;s mail settings.</li><li>Every warning, suspension, lift and deletion lands in the History pane with server name and context; rows survive the servers they describe.</li></ul><h3 id="command-history" tabindex="-1">Command History <a class="header-anchor" href="#command-history" aria-label="Permalink to &quot;Command History&quot;">​</a></h3><p>Persistent, per-server console command history: every command sent from a server&#39;s console page is stored with sender and timestamp, and the whole server team can re-run a previous command with one click.</p><ul><li><strong>Hub:</strong> <code>?a=command-history</code> — sub-tabs <strong>Overview</strong> (capture status, totals, per-server counts, the 25 most recent commands panel-wide, per-server and purge-everything actions) and <strong>Settings</strong>.</li><li><strong>Client surface:</strong> a History button anchored on the console input opens a dropdown of the server&#39;s recent commands — clicking one loads it back into the command line; a footer action clears the list. Gated by <code>websocket.connect</code>, the same permission the console needs.</li><li>Each server keeps only its newest entries (default 200, adjustable 50–1000); sending the same command twice in a row is not double-stored, and the dropdown shows the 50 newest.</li><li>Delivered as static assets through the template wrapper — no <code>yarn build</code>.</li></ul><h3 id="config-editor" tabindex="-1">Config Editor <a class="header-anchor" href="#config-editor" aria-label="Permalink to &quot;Config Editor&quot;">​</a></h3><p>Edit the panel&#39;s <code>.env</code> safely from the browser: structured rows grouped by prefix, secret masking, validation, review-before-save, and atomic writes with 10 rotating backups.</p><ul><li><strong>Hub:</strong> <code>?a=config-editor</code> — sub-tabs <strong>Editor</strong> and <strong>Raw file</strong>.</li><li><strong>Client surface:</strong> none (admin-only tool).</li><li>Never edit <code>APP_KEY</code> — encrypted panel data becomes unreadable. Changing session/cache keys logs everyone out.</li><li>Requires the <code>.env</code> to be writable by the webserver user; otherwise the pane is read-only.</li></ul><h3 id="console-log-share" tabindex="-1">Console Log Share <a class="header-anchor" href="#console-log-share" aria-label="Permalink to &quot;Console Log Share&quot;">​</a></h3><p>Copy-to-clipboard and one-click upload of the server console log to an mclogs-compatible paste service, proxied through the panel.</p><ul><li><strong>Hub:</strong> <code>?a=console-log-share</code> — single settings pane (endpoint, enable, placement) with a reset action.</li><li><strong>Client surface:</strong> server console page — a Copy Log / Share Log bar above or below the terminal, gated by <code>websocket.connect</code>.</li><li>ANSI codes are stripped server-side; oversized logs are trimmed to the configured cap.</li><li>The paste endpoint must be the mclogs-compatible <strong>API</strong> URL (default <code>https://api.mclo.gs/1/log</code>).</li></ul><h3 id="login-activity" tabindex="-1">Login Activity <a class="header-anchor" href="#login-activity" aria-label="Permalink to &quot;Login Activity&quot;">​</a></h3><p>Records every successful sign-in (password, 2FA, remember-me) with IP, user agent and timestamp, resolves each login to a coarse location with VPN/proxy badging, and mirrors live sessions with the power to revoke them.</p><ul><li><strong>Hub:</strong> <code>?a=login-activity</code> — sub-tabs <strong>Logins</strong> (full history with user and date-range filters) and <strong>Sessions</strong> (live sessions with user filter, per-row revoke and revoke-all for a compromised account).</li><li><strong>Client surface:</strong> Login Activity and Active Sessions panels on the account page (<code>/account</code>) — users review their own history with browser/OS summaries and locations, and revoke any of their own sessions except the current one.</li><li>Geolocation uses the keyless ipwho.is endpoint, one lookup per unique IP per cache window (default 30 days), cached and fail-safe; disable it entirely with <code>LOGIN_ACTIVITY_GEO=false</code>. VPN/proxy flags come from a network-name heuristic, or an optional free proxycheck.io key for an authoritative verdict.</li><li>A revoked session is logged out on its very next request; users only ever see their own records through the client API.</li></ul><h3 id="move-files" tabindex="-1">Move Files <a class="header-anchor" href="#move-files" aria-label="Permalink to &quot;Move Files&quot;">​</a></h3><p>Upgrades the file manager&#39;s move/copy UX: a browsable destination tree, copy-to-anywhere, overwrite confirmation, progress feedback, rename-while-moving and create-folder-in-dialog.</p><ul><li><strong>Hub:</strong> <code>?a=move-files</code> — informational card only; the addon has no settings.</li><li><strong>Client surface:</strong> server file manager move dialog and per-file Copy action.</li><li>Frontend-only — no routes, tables or backend; all operations go through the panel&#39;s existing client API with the user&#39;s own permissions.</li><li>Hard-refresh the Files page after install; re-run <code>install.sh</code> after panel updates overwrite the patched template.</li></ul><h3 id="node-status" tabindex="-1">Node Status <a class="header-anchor" href="#node-status" aria-label="Permalink to &quot;Node Status&quot;">​</a></h3><p>Per-server uptime tracking: status banners, daily uptime strips, incident timelines with reasons, node health views, and admin-posted service updates with optional countdowns. Plus a toggleable public status page, custom HTTP/TCP/UDP monitors, Discord incident alerts and panel-measured latency.</p><ul><li><strong>Hub:</strong> <code>?a=node-status</code> — sub-tabs <strong>Overview</strong> (settings + per-node overrides), <strong>Monitors</strong> (custom endpoints), <strong>Sharing &amp; Alerts</strong> (public page + Discord) and <strong>Service Updates</strong>.</li><li><strong>Client surface:</strong> two server sub-navigation tabs — <strong>Uptime</strong> and <strong>Service updates</strong> — gated by the <code>uptime.read</code> subuser permission, plus an unauthenticated public <code>/status</code> page with a JSON feed (<code>/api/uptime-public/summary</code>) when enabled.</li><li>Custom monitors track any external HTTP(S)/TCP/UDP endpoint alongside your nodes, with their own incident history and pause/resume; every collection tick also records round-trip latency for nodes and monitors.</li><li>The panel polls Wings on a schedule — the standard panel cron must be running; no agent on nodes. The public page is rate-limited, <code>noindex</code>, and never exposes node FQDNs.</li><li>Real node names are hidden from users unless you enable them; tracking can be toggled per node.</li></ul><h3 id="pwa" tabindex="-1">PWA <a class="header-anchor" href="#pwa" aria-label="Permalink to &quot;PWA&quot;">​</a></h3><p>Turns the whole panel into an installable app: browsers offer <em>Add to Home Screen</em> / <em>Install</em>, the panel launches in its own window with its own icon and splash colors, repeat visits load faster thanks to a service-worker cache, and users see a branded offline page instead of the browser&#39;s error page when the network drops.</p><ul><li><strong>Hub:</strong> <code>?a=pwa</code> — single settings pane (identity, appearance, icons, caching, offline page, install prompt) with live links to all endpoints and a one-click reset.</li><li><strong>Client surface:</strong> panel-wide — a dynamic manifest at <code>/pwa/manifest.json</code>, the service worker at <code>/pwa-sw.js</code>, an offline fallback at <code>/pwa/offline</code>, and a dismissible install banner (stays hidden seven days once dismissed; on iOS it shows <em>Share → Add to Home Screen</em> instructions).</li><li>Cache-first or network-first strategy for static assets, optional network-first caching of client API reads, and per-entry maximum cache age; admin pages, auth pages and <code>no-store</code> responses are never cached.</li><li>Switching the feature off makes every client unregister the service worker and purge its caches on the next page load. Requires HTTPS in production (localhost is exempt); off by default.</li></ul><h3 id="panel-logs" tabindex="-1">Panel Logs <a class="header-anchor" href="#panel-logs" aria-label="Permalink to &quot;Panel Logs&quot;">​</a></h3><p>A live view of the panel&#39;s own <code>storage/logs/*.log</code> files without SSH — and of any other log directories you point it at, such as the web server&#39;s or the Wings daemon&#39;s: tail viewer, level filters with counters, auto-refresh, download, clear and delete.</p><ul><li><strong>Hub:</strong> <code>?a=panel-logs</code> — <strong>Log files</strong> tab (grouped per source) plus a viewer tab that opens per file.</li><li><strong>Client surface:</strong> none (admin-only tool).</li><li>Sources are grouped by directory: the panel&#39;s <code>storage/logs</code> plus auto-detected Nginx (<code>/var/log/nginx</code>) and Wings (<code>/var/log/pterodactyl</code>) directories and any extra sources you configure. Unreadable sources show a plain-language notice instead of breaking the page.</li><li>Clear/delete stay available for panel logs but are hidden and refused server-side for external sources — the addon can never truncate your web server or daemon logs.</li><li>Level filters understand Laravel stack traces plus Nginx error and Wings line formats; the viewer pauses when the tab is hidden and recovers from log rotation on its own.</li></ul><h3 id="quick-files" tabindex="-1">Quick Files <a class="header-anchor" href="#quick-files" aria-label="Permalink to &quot;Quick Files&quot;">​</a></h3><p>Users pin important files and folders in the server file manager; pinned items show up as one-click chips in a collapsible Quick Access bar above the file list, so <code>server.properties</code> or the plugin config folder is always one click away.</p><ul><li><strong>Hub:</strong> <code>?a=quick-file-access</code> — single pane (enable toggle, per-server pin limit, usage stats, reset to defaults, clear every pin panel-wide).</li><li><strong>Client surface:</strong> server file manager — a star toggle on every row and the Quick Access bar with an <em>Open</em> / <em>Open Folder</em>, <em>Go to Location</em> and <em>Remove</em> context menu; <code>file.read</code> to view, <code>file.create</code> to pin.</li><li>Pins belong to the server, not to one user — everyone with file access sees the same bar; the bar hides itself when a server has no pins.</li><li>The re-check button re-validates every pin against live node listings and quietly drops pins whose target was deleted; directories that cannot be listed at that moment are left untouched, so a node hiccup never wipes pins.</li></ul><h3 id="recycle-bin" tabindex="-1">Recycle Bin <a class="header-anchor" href="#recycle-bin" aria-label="Permalink to &quot;Recycle Bin&quot;">​</a></h3><p>Deleted files move to a hidden <code>/.trash</code> folder instead of vanishing, with per-server quotas, per-egg retention windows, collision-safe restore (<code>name (restored)</code>), and an hourly purge.</p><ul><li><strong>Hub:</strong> <code>?a=recycle-bin</code> — single pane (settings, storage overview, top servers, per-egg overrides).</li><li><strong>Client surface:</strong> server file manager — a Recycle Bin toolbar button opening a full bin browser (live search, five sort orders, multi-select, restore / permanent-delete / empty), gated by the <code>trashbinpro.access</code> subuser permission.</li><li>Trashed text files preview inline and any trashed file downloads via a one-time Wings signed URL; every item carries an expiry badge, and a stats header shows item counts, total size and quota usage.</li><li>An optional toggle reroutes &quot;delete permanently&quot; requests (UI or API) through the bin too; purges from inside the bin still destroy files.</li><li>The client UI integrates at runtime — <strong>no <code>yarn build</code></strong> (a compiled SPA integration remains optional); re-run <code>install.sh</code> after panel updates.</li><li>Trashed files count against the server&#39;s real disk quota — set a capacity on shared nodes (<code>0</code> = unlimited).</li></ul><h3 id="resource-alerts" tabindex="-1">Resource Alerts <a class="header-anchor" href="#resource-alerts" aria-label="Permalink to &quot;Resource Alerts&quot;">​</a></h3><p>Watches CPU, memory, disk and network throughput of every server and notifies you the moment a server crosses a threshold — by email and optional Discord/Slack webhooks.</p><ul><li><strong>Hub:</strong> <code>?a=resource-alerts</code> — sub-tabs <strong>Overview</strong>, <strong>Rules</strong>, <strong>History</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> none; delivery is email + webhooks.</li><li>Rules layer global → per-node → per-server (most specific wins) and fire only after N consecutive 1-minute samples — no flapping, with automatic recovery notices.</li><li>Requires the panel cron (one sample per minute); use <strong>Send Test Alert</strong> after configuring channels.</li></ul><h3 id="schedule-presets" tabindex="-1">Schedule Presets <a class="header-anchor" href="#schedule-presets" aria-label="Permalink to &quot;Schedule Presets&quot;">​</a></h3><p>Administrators define named schedule templates (cron timing plus an ordered task list) once; server owners materialize them as real schedules from their server&#39;s schedules page in one click, or move schedules between servers as portable JSON documents.</p><ul><li><strong>Hub:</strong> <code>?a=schedule-presets</code> — preset CRUD (five cron fields with a quick-pick, offer-to-users toggle, only-run-when-online flag, ordered task list) plus a global switch for user-side JSON exports.</li><li><strong>Client surface:</strong> a Schedule Presets card on the server schedules page — apply a preset with a live cron/task preview, Copy JSON and Import JSON; applying and importing require the <code>schedule.create</code> subuser permission and are rate-limited like stock schedule creation.</li><li>The task editor covers the stock task types — send command, send power action, create backup (with ignored-files payload) — each with a time offset (0–900 s) and a continue-on-failure flag; cron expressions are validated server-side.</li><li>Applying honors the per-schedule task limit and refuses backup tasks when the server&#39;s backup limit is 0; every apply/import lands in the server activity log. No Wings changes, no extra cron — everything rides the stock schedule engine.</li></ul><h3 id="server-timezone" tabindex="-1">Server Timezone <a class="header-anchor" href="#server-timezone" aria-label="Permalink to &quot;Server Timezone&quot;">​</a></h3><p>Per-server timezone selection: owners pick any IANA zone from a searchable list with live clocks, and the panel feeds the zone to the container as the <code>TZ</code> environment variable so game processes, log timestamps and in-game clocks follow the server&#39;s own clock.</p><ul><li><strong>Hub:</strong> <code>?a=server-time-changer</code> — single pane (master switch, navigation label, default timezone, every server override with per-row reset).</li><li><strong>Client surface:</strong> a <strong>Timezone</strong> tab on every server&#39;s navigation — ~430 searchable zones with current UTC offset and local time, plus a ticking server clock; reading needs <code>startup.read</code>, changing needs <code>startup.update</code>.</li><li>The zone is injected through the panel&#39;s stock environment hook and synced to Wings on save; Docker cannot change a running container&#39;s environment, so the new zone applies at the next container (re)creation — the UI says exactly that.</li><li>If the node is unreachable when a change is saved, the value is stored in the panel and delivered with the next successful sync. Container images need <code>tzdata</code> (every standard yolk ships it).</li><li>Changes and resets are written to the panel&#39;s activity log.</li></ul><h3 id="server-wiper" tabindex="-1">Server Wiper <a class="header-anchor" href="#server-wiper" aria-label="Permalink to &quot;Server Wiper&quot;">​</a></h3><p>Scheduled and on-demand file wipes — built for game hosts that rotate Rust/ARK maps, but useful for any server that needs logs, cache or player data cleared on a plan.</p><ul><li><strong>Hub:</strong> <code>?a=server-wiper</code> — sub-tabs <strong>Overview</strong>, <strong>Executions</strong> and <strong>Settings</strong> (nav label, default timezone, per-server schedule limit, live-wipe policy, retention, stop grace period, Rust/ARK egg IDs, Rust map-size list).</li><li><strong>Client surface:</strong> a <strong>Wiper</strong> tab in the server sub-navigation (<code>/server/&lt;id&gt;/wiper</code>) — schedules, execution history and the per-server map library (up to 50 custom <code>.map</code> URLs), mounted inline as a native panel page.</li><li>Schedules are one-time or recurring (interval, daily, weekly, monthly or raw cron), each in its own timezone; glob patterns (<code>logs/*</code>, <code>server/?/player.db</code>) resolve against the live node listing and delete through the normal Wings repositories — a matched folder is removed whole.</li><li>Safe power handling optionally stops the server first and starts it again after (configurable grace period); a failed wipe never leaves a stopped server down. Manual &quot;Run Now&quot; requires typing <code>WIPE</code>.</li><li>Pre-wipe warning commands, post-wipe commands, rename-on-wipe with <code>{day}</code>/<code>{month}</code>/<code>{year}</code> placeholders, and per-egg Rust options (blueprint wipes, fresh random seed, fixed or random custom maps written to startup variables).</li><li>Due wipes process once per minute via the stock scheduler cron — no extra cron entries.</li></ul><h3 id="startup-presets" tabindex="-1">Startup Presets <a class="header-anchor" href="#startup-presets" aria-label="Permalink to &quot;Startup Presets&quot;">​</a></h3><p>Administrators define approved startup commands once; server owners apply them from the stock Startup page in one click — no more pasting long Java flag lines into support tickets.</p>',54)),t("ul",null,[e[2]||(e[2]=r("<li><strong>Hub:</strong> <code>?a=startup-presets</code> — sub-tabs <strong>Presets</strong> (create/edit/delete with scope badges) and <strong>Settings</strong> (optional free-form editing).</li><li><strong>Client surface:</strong> an inline picker card above the stock Startup Command box with a dropdown of every preset available for that server, an exact command preview, a confirmation dialog, and a status line showing whether the server runs the egg default, a preset or a custom command; viewing needs <code>startup.read</code>, applying needs <code>startup.update</code>.</li>",2)),t("li",null,[e[0]||(e[0]=a("Presets are scoped to every server or to selected nests/eggs; egg placeholders like ",-1)),t("code",null,l(o.SERVER_MEMORY),1),e[1]||(e[1]=a(" keep working, and users can always reset to the egg's original command.",-1))]),e[3]||(e[3]=t("li",null,[a("Free-form custom commands are off by default and can be enabled globally or per nest/egg for holders of "),t("code",null,"startup.update"),a("; every application and custom save lands in the server activity log with old/new values.")],-1))]),e[5]||(e[5]=r('<h3 id="url-download" tabindex="-1">URL Download <a class="header-anchor" href="#url-download" aria-label="Permalink to &quot;URL Download&quot;">​</a></h3><p>Users paste one or more remote URLs into a guided file-manager modal and the panel fetches the files straight into the server through Wings — no SFTP round-trip.</p><ul><li><strong>Hub:</strong> <code>?a=url-download</code> — single settings pane (policy, throughput, client experience, safeguards, history).</li><li><strong>Client surface:</strong> server file manager — a toolbar button (label configurable) with a step-by-step modal, progress popup or floating deck, and per-user URL memory chips.</li><li>Pre-flight checks include scheme/extension allow-lists and a remote HEAD probe; conflicts auto-rename, overwrite or skip per file.</li><li>Transfers run on the node via the native <code>files/pull</code> endpoint — a healthy panel↔Wings link is required.</li></ul><hr><h2 id="advanced-pack" tabindex="-1">Advanced pack <a class="header-anchor" href="#advanced-pack" aria-label="Permalink to &quot;Advanced pack&quot;">​</a></h2><h3 id="ark-mod-installer" tabindex="-1">Ark Mod Installer <a class="header-anchor" href="#ark-mod-installer" aria-label="Permalink to &quot;Ark Mod Installer&quot;">​</a></h3><p>Manage an ARK server&#39;s mod list straight from the server page — CurseForge mods for <strong>ARK: Survival Ascended</strong>, Steam Workshop mods for <strong>ARK: Survival Evolved</strong> — no FTP, no manual ini editing.</p><ul><li><strong>Hub:</strong> <code>?a=ark-mod-installer</code> — CurseForge API key, catalogue cache counters and a flush action.</li><li><strong>Client surface:</strong> an <strong>ARK Mods</strong> tab on every server; viewing needs <code>startup.read</code>, installing/removing needs <code>startup.update</code>.</li><li>Survival Ascended vs. Survival Evolved is detected from the egg (name plus well-known mod variables); ASA gets a searchable/sortable CurseForge catalogue browser with a per-mod file history dialog, ASE adds classic workshop mods by numeric id.</li><li>Installing adds the mod id to the server&#39;s startup variable (or <code>ActiveMods=</code> in <code>GameUserSettings.ini</code> when the egg has no mod variable) — the game server downloads the mods itself on the next boot; no files ever pass through the panel.</li><li>The ASA browser needs a CurseForge API key and outbound HTTPS to <code>api.curseforge.com</code> and <code>media.forgecdn.net</code>; ASE works without a key. The page reminds users to restart right where the change happens.</li></ul><h3 id="arma-reforger-tools" tabindex="-1">Arma Reforger Tools <a class="header-anchor" href="#arma-reforger-tools" aria-label="Permalink to &quot;Arma Reforger Tools&quot;">​</a></h3><p>Complete Arma Reforger server tooling on one inline server page: a workshop <strong>mod manager</strong>, a structured <strong>config editor</strong>, and an <strong>admin tools</strong> integration for the in-game admin mod — skinned from stock components so it looks native under any theme.</p><ul><li><strong>Hub:</strong> <code>?a=arma-reforger</code> — navigation label, default config file, addons path, admin-tools base path, workshop site URL and build-id override, HTTP timeout, cache TTL, per-feature toggles, collection limit, Discord webhook identity, cache statistics and a one-click flush.</li><li><strong>Client surface:</strong> <code>/server/&lt;id&gt;/arma-reforger</code>; reading anything needs <code>file.read-content</code>, changing anything needs <code>file.update</code>.</li><li>Mod installs are configuration edits (<code>game.mods</code>) — the dedicated server downloads the content itself on the next start; dependencies are pulled in automatically, and the installed view handles load order, version pinning, update badges and bulk removal.</li><li>Collections snapshot the current mod list (private or shared with the server&#39;s other users) and re-apply in one click; a guided bisection flow isolates the mod that crashes the server on start, snapshotting and restoring the original list automatically.</li><li>The config editor covers identity, scenarios, gameplay, network/A2S/RCON and limits with optimistic concurrency (a save after an external edit is refused, not silently clobbered); the admin-tools section edits the mod&#39;s JSON documents (behaviour, roster, bans, MOTD, scheduled messages, webhooks, priority queue) with a raw JSON fallback per section.</li><li>The workshop catalogue&#39;s rotating build id is auto-detected (cached 6 hours, re-detected on failure) with an override field for the rare miss.</li></ul><h3 id="backup-pro" tabindex="-1">Backup Pro <a class="header-anchor" href="#backup-pro" aria-label="Permalink to &quot;Backup Pro&quot;">​</a></h3><p>Scheduled server backups to any S3-compatible storage (AWS, Cloudflare R2, Backblaze B2, Wasabi, MinIO, Spaces) using the panel&#39;s native backup pipeline, with retention policies, offload, restore and notifications.</p><ul><li><strong>Hub:</strong> <code>?a=backup-pro</code> — sub-tabs <strong>Overview</strong>, <strong>Destinations</strong>, <strong>Backup Rules</strong>, <strong>Backups</strong>, <strong>Archives</strong>, <strong>Activity</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> server backups page — a &quot;protected by S3&quot; banner, per-backup cloud badges, optional click-to-sync, and (when enabled) cloud download/restore.</li><li>Rules combine two modes — mirror existing backups and/or create on a schedule — against all servers, a node, or hand-picked servers; credentials are encrypted with the panel app key.</li><li>Pending uploads with a red cloud icon almost always mean the queue worker (<code>standard</code> queue) is not running.</li></ul><h3 id="bedrock-addon-installer" tabindex="-1">Bedrock Addon Installer <a class="header-anchor" href="#bedrock-addon-installer" aria-label="Permalink to &quot;Bedrock Addon Installer&quot;">​</a></h3><p>Browse the Minecraft: Bedrock Edition catalogue and install behavior packs, resource packs, scripts and world templates straight onto a server — no FTP, no manual unzipping, no hand-editing of world pack lists.</p><ul><li><strong>Hub:</strong> <code>?a=bedrock-addon-installer</code> — enable toggle, CurseForge API key, section allow-list and default, egg restriction, cache lifetime, and panel-wide install records with a clear action.</li><li><strong>Client surface:</strong> a <strong>Bedrock Addons</strong> tab on every server; browsing needs <code>file.read</code>, installing needs <code>file.create</code>, uninstalling needs <code>file.delete</code>.</li><li>True one-click installs: Wings downloads and unpacks on the node, the panel reads the pack manifest, moves it into <code>behavior_packs</code> / <code>resource_packs</code> / <code>worlds</code> and registers packs in the active world&#39;s <code>world_behavior_packs.json</code> / <code>world_resource_packs.json</code>; <code>.mcaddon</code> bundles install pack by pack with live pipeline progress.</li><li>Uninstalling deletes the pack directory and drops its world registration; the Installed tab lists every recorded pack with kind, version, location and activation state.</li><li>Behaviour/resource packs activate in the world named by <code>level-name</code> (default <code>world</code>); scripts install as behavior packs; a restart is usually required. Catalogue icons are proxied through the panel, and downloads are re-derived server-side and pinned to the content CDN.</li></ul><h3 id="bedrock-version-changer" tabindex="-1">Bedrock Version Changer <a class="header-anchor" href="#bedrock-version-changer" aria-label="Permalink to &quot;Bedrock Version Changer&quot;">​</a></h3><p>Switch a Minecraft: Bedrock Edition server between official <strong>Vanilla</strong> dedicated server builds and <strong>PocketMine-MP</strong> release phars — straight from the server page, no FTP, no reinstall.</p><ul><li><strong>Hub:</strong> <code>?a=bedrock-version-changer</code> — enable toggle, flavor allow-list, wipe-option toggles, egg restriction, cache lifetime, per-server history size, and the recorded change history with a clear action.</li><li><strong>Client surface:</strong> a <strong>Bedrock Versions</strong> tab on every server; browsing needs <code>file.read</code>, changing needs <code>file.create</code>.</li><li>Builds are grouped by version line (1.21, 1.20, …) with live search, flavor filter, sorting and pagination; a guided flow (pick line → pick build → review → confirm) reports live progress from the node.</li><li>Users may wipe the server before installing, or archive the whole server into <code>backup-before-bedrock-&lt;timestamp&gt;.zip</code> first and then wipe — both options can be disabled panel-wide.</li><li>Downloads are re-derived server-side and pinned to official hosts (<code>www.minecraft.net</code>, GitHub); preview/beta builds are intentionally not offered. Every change is recorded (flavor, line, build, wipe mode, backup, user).</li></ul><h3 id="database-manager" tabindex="-1">Database Manager <a class="header-anchor" href="#database-manager" aria-label="Permalink to &quot;Database Manager&quot;">​</a></h3><p>One-click <code>.sql</code> export and streamed import for panel-managed MySQL databases, straight from the server&#39;s Databases page — no phpMyAdmin, no shared credentials.</p><ul><li><strong>Hub:</strong> <code>?a=database-manager</code> — single pane (limits, toggles, recent operations log).</li><li><strong>Client surface:</strong> server Databases page — per-database Export and Import actions, gated by the <code>databasemanager.export</code> / <code>databasemanager.import</code> subuser permissions.</li><li>Exports use <code>--single-transaction</code> so InnoDB stays writable; optional wipe-before-import when you allow it.</li><li>Requires <code>mysqldump</code>/<code>mysql</code> client binaries on the panel host; raise PHP upload limits before raising the import cap.</li></ul><h3 id="fastdl-manager" tabindex="-1">FastDL Manager <a class="header-anchor" href="#fastdl-manager" aria-label="Permalink to &quot;FastDL Manager&quot;">​</a></h3><p>Publish game server content over HTTP FastDL so players fetch maps, textures, models and sounds from a plain web server instead of the game server — with per-node download URLs and a one-click config sync.</p><ul><li><strong>Hub:</strong> <code>?a=fastdl</code> — navigation label, nest allow-list, a global default URL and per-node URL overrides.</li><li><strong>Client surface:</strong> a <strong>FastDL</strong> tab on eligible servers showing the copy-ready download URL and a sync button; viewing needs <code>file.read-content</code>, syncing needs <code>file.update</code>.</li><li>Built-in game profiles for Garry&#39;s Mod, Counter-Strike: Global Offensive and Counter-Strike 1.6 pick both the URL subdirectory and the config file (<code>garrysmod/cfg/server.cfg</code>, …); the likely profile is preselected from the egg.</li><li>Sync writes <code>sv_downloadurl</code>, <code>sv_allowdownload 1</code> and <code>sv_allowupload 1</code> through the Wings file repository — existing lines are replaced in place, comments and unrelated settings survive, and a missing config is created. Changes apply after a restart.</li><li>There is intentionally no built-in web server provisioning (that would need a node-side agent): vhost setup, TLS and file mirroring stay host-level; a minimal nginx vhost ships in the addon&#39;s README.</li></ul><h3 id="fivem-utils" tabindex="-1">FiveM Utils <a class="header-anchor" href="#fivem-utils" aria-label="Permalink to &quot;FiveM Utils&quot;">​</a></h3><p>A utilities page for FiveM servers with the day-to-day helpers a host otherwise hands to support tickets: cache clearing, game build pinning, txAdmin controls, the server artifact track and the MySQL connection string.</p><ul><li><strong>Hub:</strong> <code>?a=fivem-utils</code> — tab label, egg keywords, a review of which managed variables each matching egg defines, and a one-click variable re-sync for newly imported eggs.</li><li><strong>Client surface:</strong> a <strong>FiveM Utils</strong> tab on servers whose egg name matches the configured keywords; reads need <code>startup.read</code>, variable writes <code>startup.update</code>, the database helper <code>database.update</code> and the cache cleaner <code>file.delete</code>.</li><li>Each card renders only when the egg defines the backing variable (<code>GAME_BUILD</code>, <code>TXADMIN_ENABLE</code> / <code>TXADMIN_PORT</code>, <code>ARTIFACT_URL</code>, <code>MYSQL_CONNECTION_STRING</code>); the installer adds them to every egg matching <code>fivem</code>, <code>txadmin</code> or <code>cfx</code> automatically.</li><li>The database helper writes a ready-to-use <code>mysql://…</code> string into the hidden variable without ever showing credentials; the artifact picker uses the public artifact feed (cached, with a static fallback).</li><li>The addon sets variables only — the txAdmin port must be free on the node, and the egg&#39;s install script must actually consume <code>ARTIFACT_URL</code>. Changes apply after a restart (artifacts on the next reinstall).</li></ul><h3 id="git-source-control" tabindex="-1">Git Source Control <a class="header-anchor" href="#git-source-control" aria-label="Permalink to &quot;Git Source Control&quot;">​</a></h3><p>Full git source control for game servers inside the client panel: users link their Git provider account with a fine-grained personal access token, clone a repository into a server, then stage, commit, pull and push — no SFTP round-trips, no command line.</p><ul><li><strong>Hub:</strong> <code>?a=github-source-control</code> — host diagnostics (git version, volume root, linked accounts), settings (navigation label, allowed nests, allowed git hosts, push toggle, manual-URL toggle) and every linked account with one-click revoke.</li><li><strong>Client surface:</strong> <code>/server/&lt;id&gt;/source-control</code> mounted inline — working-tree status, per-file stage/unstage/discard, commit, fetch/pull/push, a line-diff viewer, branches, the 50 most recent commits and a sub-repository path switcher; reads need <code>file.read-content</code>, staging/commit/push need <code>file.update</code>, clone/pull need <code>file.create</code>.</li><li>Tokens are validated against the GitHub API on connect, stored encrypted, and passed per command as an HTTP header — never written into the server&#39;s <code>.git/config</code>; pulls are fast-forward-only with a clear message on divergence.</li><li>Git operations run panel-side against <code>&lt;volume_root&gt;/&lt;server uuid&gt;</code> using the host&#39;s <code>git</code> binary — servers whose volume is not mounted on the panel host (remote nodes without shared storage) show a clear &quot;files not reachable&quot; state instead of failing obscurely.</li><li><code>GSC_API_BASE</code> can point at a GitHub Enterprise Server; clone/fetch/pull/push themselves are plain git over HTTPS and work with any host on the allow-list.</li></ul><h3 id="hytale-mod-installer" tabindex="-1">Hytale Mod Installer <a class="header-anchor" href="#hytale-mod-installer" aria-label="Permalink to &quot;Hytale Mod Installer&quot;">​</a></h3><p>Browse, search and install Hytale mods from the CurseForge Hytale catalogue directly on the server page — no FTP, no manual downloads.</p><ul><li><strong>Hub:</strong> <code>?a=hytale-mod-installer</code> — CurseForge API key (the install directory lives in config, default <code>/mods</code>).</li><li><strong>Client surface:</strong> a <strong>Hytale Mods</strong> tab on every server — servers whose egg does not look like Hytale see an explanatory notice instead of the catalogue; browsing needs <code>file.read</code>, installing needs <code>file.create</code>, removing needs <code>file.delete</code>.</li><li>One-click install drops the newest file into <code>/mods</code>; the Versions dialog picks a specific file with its own text filter and paging; the installed list shows file sizes and dates with a confirmed removal step.</li><li>The panel only resolves the download URL — Wings fetches the file directly onto the node.</li><li>CurseForge is currently the only public mod repository with a real Hytale section, so it is the only provider; the provider layer stays pluggable if that changes.</li></ul><h3 id="hytale-world-manager" tabindex="-1">Hytale World Manager <a class="header-anchor" href="#hytale-world-manager" aria-label="Permalink to &quot;Hytale World Manager&quot;">​</a></h3><p>Browse the CurseForge Hytale world catalogue, install worlds onto a server with one click, choose which world the server loads, and remove worlds again — all from the server page.</p><ul><li><strong>Hub:</strong> <code>?a=hytale-world-manager</code> — CurseForge API key (the same key as the Hytale Mod Installer works) plus a panel-wide managed-world count.</li><li><strong>Client surface:</strong> a <strong>Hytale Worlds</strong> tab on every server; browsing needs <code>file.read</code>, installing needs <code>file.create</code>, activating needs <code>file.update</code>, removing needs <code>file.delete</code>.</li><li>A current-world banner shows which folder the server loads; a guided install (latest or a specific version, with a &quot;load after installation&quot; checkbox) downloads and extracts directly on the node into <code>/universe/worlds</code> — no data passes through the panel.</li><li>Activation rewrites <code>Defaults.World</code> in the server&#39;s <code>config.json</code> (both known layouts probed); worlds dropped onto the node manually are listed alongside catalogue installs, and the currently loaded world cannot be removed.</li><li>Hytale rewrites its config while running — activate while the server is offline; the change always applies on the next start.</li></ul><h3 id="mod-installer" tabindex="-1">Mod Installer <a class="header-anchor" href="#mod-installer" aria-label="Permalink to &quot;Mod Installer&quot;">​</a></h3><p>Browse, search and install Minecraft mods from Modrinth and CurseForge directly on the server page; the panel resolves the URL and Wings fetches the file into <code>/mods</code>.</p><ul><li><strong>Hub:</strong> <code>?a=mod-installer</code> — single settings pane (CurseForge key, default provider, default loader) with provider status badges.</li><li><strong>Client surface:</strong> a <strong>Mods</strong> tab on every server&#39;s navigation with loader/version filters, sorting and a versions dialog; browsing needs <code>file.read</code>, installing needs <code>file.create</code>, uninstalling and updating additionally need <code>file.delete</code>.</li><li>Installs run as tracked background jobs with live progress polling instead of a blocking request; the installed-mod list sorts by name, size or date and removes any file with a two-step confirm.</li><li>Installed jars are SHA-512 fingerprinted and matched against Modrinth — outdated mods show the newer release with a one-click update that downloads the new file and removes the old one once it has landed (CurseForge files cannot be fingerprint-matched and report as untracked).</li><li>Modrinth works out of the box; CurseForge unlocks once you save an API key. Catalogue responses are cached panel-side (default 5 minutes) to keep rate limits happy; nodes must reach the mod CDNs.</li></ul><h3 id="modpack-installer" tabindex="-1">Modpack Installer <a class="header-anchor" href="#modpack-installer" aria-label="Permalink to &quot;Modpack Installer&quot;">​</a></h3><p>One-click Modrinth and CurseForge modpack installs from the file manager — full version lists, a confirmation screen with exact file counts, and live per-file progress.</p><ul><li><strong>Hub:</strong> <code>?a=modpack-installer</code> — settings pane (health badges, usage counters, recent installs) plus an <strong>Installs</strong> sub-tab with currently running tasks and every pack tracked as installed panel-wide.</li><li><strong>Client surface:</strong> a <strong>Modpacks</strong> button in the server file manager opening the browse/install wizard, plus per-server install history.</li><li>Installs run fully server-side as a phased pipeline (fetch → pack → backup → wipe → transfer → extract) that the wizard polls for progress; closing or reloading the wizard does not lose the task — reopening re-attaches to the running install.</li><li>Three install modes: standard merge, <em>wipe, then install</em>, and <em>back up, wipe, then install</em> (current files are zipped into a <code>modpack-backup-&lt;date&gt;</code> archive left in the target directory first); both destructive modes are operator-gated.</li><li>Every completed install records its full file manifest — the wizard&#39;s &quot;Installed on this server&quot; block uninstalls a tracked pack with a two-click confirm, removing exactly the manifest files and nothing else. Installs completed before 1.1.0 have no manifest and cannot be uninstalled from the wizard.</li><li>Installs files only — egg, Docker image and startup jar are untouched; requires the PHP <code>zip</code> extension and a writable staging directory (both shown as pane badges). Nodes pull the install bundle back from the panel URL; small bundles (≤ 32 MB) are pushed through the daemon write endpoint when a node cannot reach the panel.</li></ul><h3 id="node-stats" tabindex="-1">Node Stats <a class="header-anchor" href="#node-stats" aria-label="Permalink to &quot;Node Stats&quot;">​</a></h3><p>Fleet-wide analytics: CPU/RAM/disk/bandwidth time-series, per-node drill-downs, multi-tier historical aggregates, capacity exhaustion forecasts, top consumers, and downloadable daily/weekly/monthly reports.</p><ul><li><strong>Hub:</strong> <code>?a=node-stats</code> — sub-tabs <strong>Overview</strong>, <strong>Nodes</strong>, <strong>Capacity</strong>, <strong>Historical</strong>, <strong>Top Consumers</strong>, <strong>Reports</strong>, <strong>Settings</strong>.</li><li><strong>Client surface:</strong> none (admin-only dashboards).</li><li>Charts use a locally bundled Chart.js — zero external requests.</li><li>Needs both the panel cron <strong>and</strong> a Supervisor worker on the <code>nodeanalytics</code> queue (<code>data/install-queue-worker.sh</code> sets it up); empty dashboards mean one of the two is missing.</li></ul><h3 id="permission-manager" tabindex="-1">Permission Manager <a class="header-anchor" href="#permission-manager" aria-label="Permalink to &quot;Permission Manager&quot;">​</a></h3><p>Delegate admin work safely: staff roles, members, scoped assignments and a restricted staff area at <code>/admin/staff</code> — without ever granting <code>root_admin</code>.</p><ul><li><strong>Hub:</strong> <code>?a=permission-manager</code> — sub-tabs <strong>Overview</strong>, <strong>Roles</strong>, <strong>Members</strong>, <strong>Audit Log</strong>.</li><li><strong>Client surface:</strong> no new client pages — staff reach in-scope servers as real, auto-provisioned Pterodactyl subusers (default: console, power actions, file read), enforced natively by the panel.</li><li>Roles control which staff pages open, whether members see all or only assigned users/servers, and whether they may edit server build configuration; every write lands in the audit log.</li><li>Role deletion is refused while members are assigned; before uninstalling, remove members or run <code>php artisan permgr:sync</code> so no provisioned subusers remain.</li></ul><h3 id="player-list" tabindex="-1">Player List <a class="header-anchor" href="#player-list" aria-label="Permalink to &quot;Player List&quot;">​</a></h3><p>A live online-player card with an <code>online / max</code> badge on the server console page, self-refreshing without reloads.</p><ul><li><strong>Hub:</strong> <code>?a=player-list</code> — single settings pane (enable, protocol, avatar and action toggles, timeout/cache/refresh) with a built-in host:port test tool.</li><li><strong>Client surface:</strong> server console page — a Players card beneath the terminal polling the client API at your configured interval.</li><li>Each row shows the player&#39;s head avatar (provider URL configurable, local placeholder on load failure), and busy servers get a type-to-filter box with a &quot;showing x of y&quot; counter.</li><li>Row moderation actions (kick, ban with reason, op/deop, gamemode, whitelist add/remove) are sent as plain console commands, logged in the server activity log, and only appear for users with console access.</li><li>When a server answers the ping but not the query, the card explains that only a sample is shown and offers an <strong>Enable query</strong> button (visible to users with the file-edit permission) that rewrites <code>enable-query=true</code> and <code>query.port</code> in <code>server.properties</code> — a restart is required.</li><li>UDP query returns the full list but needs <code>enable-query=true</code>; the status-ping fallback needs no setup but returns only a name sample. Results are cached per server; the card degrades quietly when a server is offline.</li></ul><h3 id="player-manager" tabindex="-1">Player Manager <a class="header-anchor" href="#player-manager" aria-label="Permalink to &quot;Player Manager&quot;">​</a></h3><p>Manage Minecraft Java players over plain RCON from the client panel: online list, moderation, player actions, server controls and an offline roster. Nothing is installed on the node.</p><ul><li><strong>Hub:</strong> <code>?a=player-manager</code> — single settings pane (enable, avatars and player-data toggles, default port, timeouts) plus the stored-credentials table with revocation.</li><li><strong>Client surface:</strong> a <strong>Players</strong> page on every server&#39;s navigation, including a per-server RCON connection form (stored encrypted); viewing needs <code>websocket.connect</code>, every action needs <code>control.console</code>, and every action hits the activity log.</li><li>Beyond kick/ban/unban, op/deop and whitelist management: gamemode switch, give items, clear inventory, set/add XP, heal, feed, potion effects, plus time, weather, difficulty and game-rule controls with current values read back.</li><li>The offline roster merges whitelist, ban list, ops and join cache with the live online list — searchable, works while the server is stopped; the player-data viewer reads <code>playerdata/*.dat</code> through the node (vitals, XP, position, inventory, ender chest) and edits documented scalar fields offline, keeping a <code>.pm-backup</code> on the node before every write.</li><li>One-click <strong>Fix RCON</strong> writes <code>enable-rcon=true</code>, <code>rcon.port</code> and <code>rcon.password</code> into <code>server.properties</code> through the node&#39;s file API, generating and storing a password when the server has none; avatars are served through a caching panel-side proxy.</li><li>Credentials resolve per-server override → <code>RCON_PASSWORD</code>/<code>RCON_PORT</code>/<code>RCON_HOST</code> server variables → defaults; the RCON port must be reachable from the panel host.</li></ul><h3 id="plugin-installer" tabindex="-1">Plugin Installer <a class="header-anchor" href="#plugin-installer" aria-label="Permalink to &quot;Plugin Installer&quot;">​</a></h3><p>Search Modrinth, Hangar, Spiget, CurseForge and Polymart from the server page and install plugins straight into <code>/plugins</code> — with an installed-plugin library and SHA-512 update hints.</p><ul><li><strong>Hub:</strong> <code>?a=plugin-installer</code> — single settings pane (provider toggles, CurseForge key, install directory, analysis cap).</li><li><strong>Client surface:</strong> a <strong>Plugins</strong> page on every server&#39;s navigation with provider/software/version filters, catalogue sorting, a per-plugin details modal, per-release install buttons, and an Installed tab with one-click updates; browsing needs <code>file.read</code>, installing needs <code>file.create</code>, uninstalling needs <code>file.delete</code>.</li><li>Installs run asynchronously with a live progress dialog (resolving → downloading) driven by polling; the Installed tab removes jars after a confirmation (plugin configuration folders stay on the server).</li><li>Premium/external resources are marked and never pulled; CurseForge and Polymart are off by default. Catalogue responses are cached panel-side (TTL tunable via <code>catalogue_cache_ttl</code>).</li><li>Wings performs the actual downloads — nodes must reach the provider CDNs.</li></ul><h3 id="reverse-proxy" tabindex="-1">Reverse Proxy <a class="header-anchor" href="#reverse-proxy" aria-label="Permalink to &quot;Reverse Proxy&quot;">​</a></h3><p>Managed reverse proxy rules for game servers: users point a domain at one of their server&#39;s allocations, pick an SSL mode, and the panel tracks the rule — including whether the domain&#39;s DNS already resolves to the node&#39;s address.</p><ul><li><strong>Hub:</strong> <code>?a=reverse-proxy</code> — sub-tabs <strong>Settings</strong> (allowed nodes, default per-server limit, whitelist mode), <strong>Whitelist</strong> (per-server limit overrides with a server search picker) and <strong>All Proxies</strong> (every rule on the panel, with delete for moderation).</li><li><strong>Client surface:</strong> a <strong>Reverse Proxy</strong> tab on every server; reads need <code>allocation.read</code>, writes need <code>allocation.update</code>.</li><li>Three SSL modes — plain HTTP, Let&#39;s Encrypt (contact email stored for issuance/expiry notices) or a custom certificate chain + key; certificate material is write-only and never leaves the panel again.</li><li>On save the domain is checked against the node&#39;s public addresses, so the rule shows &quot;DNS verified&quot; or &quot;DNS pending&quot;; each rule can render a copy-paste nginx server block for the machine that terminates web traffic.</li><li>The panel stores and validates the rule set only — actually answering traffic needs a web server on the node configured from the rule. The competitor&#39;s automatic node-side provisioning needs a node agent and is deliberately not included. Raw TCP/UDP game protocols are better served by SRV records (see Subdomain Manager).</li></ul><h3 id="server-importer" tabindex="-1">Server Importer <a class="header-anchor" href="#server-importer" aria-label="Permalink to &quot;Server Importer&quot;">​</a></h3><p>Move servers from another Pterodactyl panel using the source&#39;s Application API: stored connections, inventory fetch, dry run with a full conflict report, execution, and one-click rollback.</p><ul><li><strong>Hub:</strong> <code>?a=server-importer</code> — sub-tabs <strong>Overview</strong> and <strong>Run report</strong>.</li><li><strong>Client surface:</strong> none (root-admin tool).</li><li>A dry run creates nothing — it reports user matches, egg matches, allocation claims and dropped environment values; claims are re-verified before execution, and rollback force-deletes everything a run created.</li><li>Needs a <code>ptla_…</code> key on the source panel with read access to servers, users, nodes, nests and eggs, and a target node with enough free allocations.</li></ul><h3 id="server-properties" tabindex="-1">Server Properties <a class="header-anchor" href="#server-properties" aria-label="Permalink to &quot;Server Properties&quot;">​</a></h3><p>A friendly, categorized <code>server.properties</code> editor for Minecraft servers — plus a MOTD editor with live preview, a server icon manager and an auto-detected YAML configuration editor.</p><ul><li><strong>Hub:</strong> <code>?a=server-properties</code> — single settings pane (tab label, file name, allowed nests, descriptions, and per-feature toggles for the MOTD, icon and YAML editors).</li><li><strong>Client surface:</strong> a <strong>Properties</strong> tab on eligible servers (default: nest <code>1</code>, the stock Minecraft nest); reads need <code>file.read-content</code>, writes need <code>file.update</code>, icon uploads need <code>file.create</code>, icon removal needs <code>file.delete</code>.</li><li>The options editor keeps its typed inputs (toggles, dropdowns, clamped numbers), per-key descriptions, live search and dirty tracking; writes go through the Wings file repository so comments, blank lines and key order survive.</li><li>The MOTD editor handles legacy <code>§</code> codes, MiniMessage tags and raw text with a live multiplayer-list preview; the icon manager center-crops any image to exactly 64×64 PNG (verified again server-side).</li><li>Every root-level <code>.yml</code>/<code>.yaml</code> file opens in a structured editor (typed rows, nesting, filter box) with per-key descriptions for BungeeCord-style proxy configs; a raw mode covers hand-tuned files, and the server validates YAML before writing.</li><li>Changes apply after a server restart — Minecraft reads the file at boot.</li></ul><h3 id="server-splitter" tabindex="-1">Server Splitter <a class="header-anchor" href="#server-splitter" aria-label="Permalink to &quot;Server Splitter&quot;">​</a></h3><p>Let your users split one big server into several smaller ones: the owner picks how much CPU, RAM, disk, ports, databases and backups to carve out, and the addon creates a sub-server on the same node, egg and startup configuration — debited immediately, handed back on removal.</p><ul><li><strong>Hub:</strong> <code>?a=server-splitter</code> — sub-tabs <strong>Overview</strong>, <strong>Whitelist</strong>, <strong>Splits</strong>, <strong>Link Servers</strong> and <strong>Settings</strong> (safety-rail minimums, unlimited policy, whitelist modes).</li><li><strong>Client surface:</strong> a <strong>Splitter</strong> tab at <code>/server/&lt;id&gt;/splitter</code>, visible to the server owner (and root admins) only — remaining splittable resources, allowance usage, and existing sub-servers with resize/rename/remove.</li><li>Split allowances come from a per-server whitelist with fixed limits or resource-graded rules (&quot;a server with at least 1 GB RAM may run 2 sub-servers&quot;) checked in an admin-defined priority order; whitelist-only mode and a higher-of-both fallback are both supported.</li><li>Safety rails: configurable minimums that must remain on the master, minimums every sub-server must receive, a node free-port check, and a hard block on splitting a sub-server further; optional subuser sync copies the master&#39;s subusers onto a new sub-server.</li><li>Admin linking attaches an existing standalone server to a master without moving resources; <code>php artisan server-splitter:reconcile</code> repairs the books after sub-servers are deleted outside the splitter.</li><li>If the node is unreachable at creation, the sub-server stays in the <em>installing</em> state with the bookkeeping intact — reinstall it (or remove the split) once the node answers.</li></ul><h3 id="server-type-changer" tabindex="-1">Server Type Changer <a class="header-anchor" href="#server-type-changer" aria-label="Permalink to &quot;Server Type Changer&quot;">​</a></h3><p>Let server owners move their server to a different <strong>egg</strong> — or, when you allow it, a different <strong>nest</strong> — from a guided page in the client panel, while administrators keep full control via global flags, per-server whitelists and blocked nests/eggs.</p><ul><li><strong>Hub:</strong> <code>?a=server-type-changer</code> — sub-tabs <strong>Overview</strong> (enable toggle, nest/egg change flags, blocked nests/eggs, history retention, the last 25 change runs) and <strong>Whitelist</strong> (per-server grants by short identifier or UUID).</li><li><strong>Client surface:</strong> a guided page at <code>/server/&lt;id&gt;/type-changer</code> (pick target type → choose data handling → review → confirm), gated by the <code>settings.reinstall</code> subuser permission — server owners always pass; without a whitelist grant the nav entry stays hidden.</li><li>Data handling per change: keep all files, wipe server data (prominent warning), or backup-and-wipe — a <strong>locked</strong> safety backup is created first, and if it cannot be started, nothing is changed. An optional reinstall runs the new egg&#39;s installation script.</li><li>Startup variables that exist under the same environment name on both eggs keep their values; everything else resets to the new egg&#39;s defaults. Docker images carry over when the new egg offers them.</li><li>Unreachable-node steps complete as <em>completed with warnings</em> with the exact failed step recorded; suspended, installing, restoring or transferring servers cannot be changed until they settle.</li></ul><h3 id="staff-requests" tabindex="-1">Staff Requests <a class="header-anchor" href="#staff-requests" aria-label="Permalink to &quot;Staff Requests&quot;">​</a></h3><p>Users request server access from each other — by server ID or owner email — with owner approval, three permission presets, temporary access, blocking and a full audit trail. Approved requests create real subusers. Owners can also flip the flow around and ask a designated staff member for help.</p><ul><li><strong>Hub:</strong> <code>?a=staff-requests</code> — single pane (access policy, limits, stats, staff roster management, read-only requests/grants/audit tables).</li><li><strong>Client surface:</strong> Account → Staff Requests (<code>/account/server-access</code>) plus an Access Manager shortcut on the server Users page for owners and holders of the <code>accessmanager.manage</code> permission.</li><li>Any request can be marked urgent (requires a short message, floats to the top with a red badge), and every request carries a sanitized free-text reason — reused as the &quot;what do you need help with?&quot; description on help requests.</li><li>Owner-initiated <strong>Request Staff Help</strong> reverses the direction: the owner picks a server and a staff member from the admin-curated roster (added by email, with role labels like &quot;Support&quot;); when the staff member approves, <em>they</em> receive the subuser access. Roster usernames are shown to users; emails are never exposed.</li><li>Temporary access (1 hour to 30 days) is revoked automatically by the panel cron, including SFTP session invalidation; the email flow never reveals account existence, and uninstalling does not remove already-granted subusers.</li></ul><h3 id="subdomain-manager" tabindex="-1">Subdomain Manager <a class="header-anchor" href="#subdomain-manager" aria-label="Permalink to &quot;Subdomain Manager&quot;">​</a></h3><p>Self-service DNS for game servers: users create A and SRV records on the Network page, provisioned through the Cloudflare API against zones you control.</p><ul><li><strong>Hub:</strong> <code>?a=subdomain-manager</code> — sub-tabs <strong>Settings</strong>, <strong>Domains</strong>, <strong>Records</strong> and <strong>Limits</strong> (per-server quota overrides, node allow/deny policy).</li><li><strong>Client surface:</strong> a Subdomains card on the server Network page, gated by the <code>subdomainplus.read</code> / <code>create</code> / <code>delete</code> subuser permissions.</li><li>The create form verifies the chosen subdomain as you type (format, banned patterns, local records and the zone itself) and blocks known-taken names; <strong>Fetch zones from Cloudflare</strong> auto-fills domain + Zone ID from your account.</li><li>When the allocation alias is a hostname, an A request is transparently upgraded to a <strong>CNAME</strong> pointing at that hostname (per-domain toggle); SRV records point at stable per-allocation hostnames that survive IP changes, and records are always created unproxied.</li><li>Per domain you can restrict eggs, ban names via regex, force a target IP, and define SRV presets; per-server quota overrides and node allow/deny rules live on the Limits tab (restricted servers keep managing existing records). Keep the panel cron running for sync and orphan cleanup; records are de-provisioned automatically when a server is deleted.</li></ul><h3 id="version-changer" tabindex="-1">Version Changer <a class="header-anchor" href="#version-changer" aria-label="Permalink to &quot;Version Changer&quot;">​</a></h3><p>Let users switch a server&#39;s Minecraft: Java Edition software and version from the panel — Vanilla (releases, snapshots, historic builds) plus Paper, Purpur, Folia, Velocity and Waterfall down to an exact build, with automatic jar backups, optional data wipe choices and live install progress.</p><ul><li><strong>Hub:</strong> <code>?a=version-changer</code> — settings pane with a recent-changes table, plus a <strong>Server Access</strong> sub-tab for per-server grants.</li><li><strong>Client surface:</strong> a Version Changer card on the server Startup page; viewing needs <code>file.read</code>, installing needs <code>file.create</code>.</li><li>The picker walks software → game version → build (build numbers, channels, dates, sizes, latest markers and commit summaries for build-based software); per install the user chooses to keep files, archive-then-wipe (a zip of the whole server stays behind) or wipe — wipe options can be disabled panel-wide.</li><li>The picker polls a per-server progress endpoint and shows the running step (resolving → archiving → wiping → downloading → finalizing); installs are recorded with software, version, build, filename, backup/archive and wipe mode.</li><li>Jar downloads are pinned to the official distribution hosts of each software regardless of the manifest endpoints; the previous jar is renamed to <code>&lt;name&gt;.backup-&lt;timestamp&gt;</code> on keep-files installs, and the egg&#39;s <code>SERVER_JARFILE</code> variable can be pointed at the new jar automatically.</li><li>The running process keeps the old jar until the next restart — tell users to restart after switching.</li></ul><h3 id="votifier-tester" tabindex="-1">Votifier Tester <a class="header-anchor" href="#votifier-tester" aria-label="Permalink to &quot;Votifier Tester&quot;">​</a></h3><p>Send a real test vote from the client panel to any Votifier/NuVotifier listener and instantly see whether delivery succeeds — the fastest way to debug vote listener host, port, token and key setup.</p><ul><li><strong>Hub:</strong> <code>?a=votifier-tester</code> — single pane (global feature toggle, default listener port, connection timeouts).</li><li><strong>Client surface:</strong> a <strong>Votifier</strong> page on every server&#39;s navigation; viewing needs <code>websocket.connect</code>, sending a test needs <code>control.console</code>, and every test lands in the server&#39;s activity log.</li><li>Speaks both wire protocols — Votifier v1 (RSA-sealed vote block) and NuVotifier v2 (HMAC-SHA-256 signed JSON) — with auto-detect from the listener&#39;s handshake banner; the result shows the banner, any reply, the detected protocol and the round-trip time.</li><li>The page keeps the session&#39;s recent attempts (target, protocol, outcome, duration) for quick iteration; token and public key travel with the test only — the panel never persists them.</li><li>Zero node footprint: the panel talks straight to the listener, whose port must be reachable from the panel host. A well-formed vote is answered with silence, so a clean handshake plus transmission counts as a pass — the reward event shows up in the server console.</li></ul><h3 id="world-manager" tabindex="-1">World Manager <a class="header-anchor" href="#world-manager" aria-label="Permalink to &quot;World Manager&quot;">​</a></h3><p>Browse the CurseForge world catalogue, install a world onto a server with one click, and point the server at any of its world directories — no FTP, no manual uploads.</p><ul><li><strong>Hub:</strong> <code>?a=mc-world-manager</code> — CurseForge API key, default catalogue sort, navigation label, catalogue cache lifetime.</li><li><strong>Client surface:</strong> a <strong>Worlds</strong> tab on every server; browsing needs <code>file.read</code>, installing needs <code>file.create</code>, deleting needs <code>file.delete</code>, switching the active world needs <code>file.update</code>.</li><li>Each world card opens a versions dialog (game versions, release channel, size, download count); a confirmation step explains what happens, and a progress dialog follows the real install (downloading → extracting → moving) instead of a dead spinner.</li><li>Smart unpacking stages the archive in a hidden folder, and the directory containing <code>level.dat</code> is moved to the server root under a collision-free name; archives Wings cannot unpack (rar, 7z, plain gzip) are rejected with a clear message.</li><li>Every root directory holding a <code>level.dat</code> is listed with its modification date; switching the active world rewrites <code>level-name</code> in <code>server.properties</code> (restart to play), and deletes verify the directory really is a world first. Catalogue responses are cached panel-side.</li></ul><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every setting on every pane, with defaults.</li><li><strong><a href="./dashboard">The Hub Dashboard →</a></strong> — layout, sub-tabs and the save round-trip.</li></ul>',92))])}const v=s(d,[["render",c]]);export{f as __pageData,v as default};
